import React, { useEffect, useMemo, useRef, useState } from 'react';
import { io } from 'socket.io-client';
import { useNavigate } from 'react-router-dom';
import { api, normalizeTrades, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

function formatTime(ts) {
  if (!ts) return '—';
  try {
    return new Date(ts).toLocaleString();
  } catch {
    return ts;
  }
}

function TrendChart({ logs }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const width = canvas.offsetWidth || 520;
    const height = 280;

    canvas.width = width * 2;
    canvas.height = height * 2;
    canvas.style.height = `${height}px`;

    const ctx = canvas.getContext('2d');
    ctx.scale(2, 2);
    ctx.clearRect(0, 0, width, height);

    const data = [...(logs || [])]
      .filter((log) => !String(log?.reason || '').includes('Circular trading loop detected'))
      .slice(0, 20)
      .reverse()
      .map((log, idx) => ({
        x: idx + 1,
        y: Number(log?.risk_score || 0),
      }));

    const padL = 46;
    const padR = 18;
    const padT = 20;
    const padB = 40;
    const chartW = width - padL - padR;
    const chartH = height - padT - padB;

    const bg = ctx.createLinearGradient(0, 0, 0, height);
    bg.addColorStop(0, 'rgba(122,255,212,0.08)');
    bg.addColorStop(1, 'rgba(122,255,212,0)');
    ctx.fillStyle = bg;
    ctx.fillRect(padL, padT, chartW, chartH);

    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    for (let y = 0; y <= 100; y += 20) {
      const py = padT + chartH - (y / 100) * chartH;
      ctx.beginPath();
      ctx.moveTo(padL, py);
      ctx.lineTo(width - padR, py);
      ctx.stroke();

      ctx.fillStyle = '#789089';
      ctx.font = '11px Inter';
      ctx.fillText(String(y), 16, py + 4);
    }

    ctx.strokeStyle = 'rgba(255,255,255,0.16)';
    ctx.beginPath();
    ctx.moveTo(padL, padT);
    ctx.lineTo(padL, padT + chartH);
    ctx.lineTo(width - padR, padT + chartH);
    ctx.stroke();

    ctx.fillStyle = '#d7e7e0';
    ctx.font = '12px Inter';
    ctx.fillText('Risk score', 10, 14);
    ctx.fillText('Latest non-loop suspicious events', width / 2 - 82, height - 10);

    if (!data.length) {
      ctx.fillStyle = '#70817b';
      ctx.fillText('No abnormal-price / non-loop risk events yet', padL + 12, padT + chartH / 2);
      return;
    }

    const points = data.map((d, i) => ({
      x: padL + (i / Math.max(data.length - 1, 1)) * chartW,
      y: padT + chartH - (d.y / 100) * chartH,
      raw: d.y,
      label: d.x,
    }));

    const area = ctx.createLinearGradient(0, padT, 0, padT + chartH);
    area.addColorStop(0, 'rgba(98,223,255,0.22)');
    area.addColorStop(1, 'rgba(98,223,255,0.01)');

    ctx.beginPath();
    points.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.lineTo(points[points.length - 1].x, padT + chartH);
    ctx.lineTo(points[0].x, padT + chartH);
    ctx.closePath();
    ctx.fillStyle = area;
    ctx.fill();

    ctx.beginPath();
    points.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.strokeStyle = '#7fffd4';
    ctx.lineWidth = 3;
    ctx.shadowColor = 'rgba(127,255,212,0.24)';
    ctx.shadowBlur = 16;
    ctx.stroke();
    ctx.shadowBlur = 0;

    points.forEach((p, i) => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4.2, 0, Math.PI * 2);
      ctx.fillStyle =
        p.raw >= 70 ? '#ff7f8d' : p.raw >= 40 ? '#ffc15d' : '#7fffd4';
      ctx.fill();

      if (i % 2 === 0 || points.length <= 8) {
        ctx.fillStyle = '#748883';
        ctx.font = '10px Inter';
        ctx.fillText(String(p.label), p.x - 3, padT + chartH + 16);
      }
    });
  }, [logs]);

  return <canvas ref={canvasRef} style={{ width: '100%', display: 'block' }} />;
}

function StatCard({ label, value, sub, accent = '#74ffb7' }) {
  return (
    <div
      style={{
        padding: 20,
        borderRadius: 20,
        background:
          'linear-gradient(180deg, rgba(8,28,18,0.88), rgba(3,10,7,0.84))',
        border: '1px solid rgba(96,255,166,0.10)',
        boxShadow:
          'inset 0 1px 0 rgba(255,255,255,0.03), 0 10px 30px rgba(0,0,0,0.28)',
        backdropFilter: 'blur(16px)',
        WebkitBackdropFilter: 'blur(16px)',
      }}
    >
      <div style={{ color: '#7e978b', fontSize: 12, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase' }}>
        {label}
      </div>
      <div style={{ color: accent, fontSize: 38, fontWeight: 900, marginTop: 12 }}>
        {value}
      </div>
      <div style={{ color: '#5f766b', fontSize: 13, marginTop: 8 }}>{sub}</div>
    </div>
  );
}

function DarkGlassPanel({ title, subtitle, right, children }) {
  return (
    <div
      style={{
        overflow: 'hidden',
        borderRadius: 22,
        background:
          'linear-gradient(180deg, rgba(8,28,18,0.90), rgba(4,10,8,0.86))',
        border: '1px solid rgba(82,217,142,0.10)',
        boxShadow:
          'inset 0 1px 0 rgba(255,255,255,0.025), 0 16px 40px rgba(0,0,0,0.34)',
        backdropFilter: 'blur(18px)',
        WebkitBackdropFilter: 'blur(18px)',
      }}
    >
      <div
        style={{
          padding: '18px 20px',
          borderBottom: '1px solid rgba(255,255,255,0.05)',
          display: 'flex',
          justifyContent: 'space-between',
          gap: 12,
          alignItems: 'center',
        }}
      >
        <div>
          <div style={{ fontSize: 17, fontWeight: 900, color: '#dbefe5' }}>{title}</div>
          {subtitle ? (
            <div style={{ color: '#73897f', fontSize: 12, marginTop: 6 }}>{subtitle}</div>
          ) : null}
        </div>
        {right}
      </div>
      {children}
    </div>
  );
}

export default function DashboardPage() {
  const navigate = useNavigate();
  const [stats, setStats] = useState({});
  const [trades, setTrades] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [cycles, setCycles] = useState([]);

  const loadAll = async () => {
    try {
      const [statsRes, tradesRes, riskRes, cycleRes] = await Promise.all([
        api.fetchStats(),
        api.fetchTrades(1, 50),
        api.fetchFraudLogs(),
        api.fetchFraudCycles(),
      ]);

      setStats(statsRes || {});
      setRiskLogs(riskRes || []);
      setTrades(normalizeTrades(tradesRes || [], riskRes || []));
      setCycles(cycleRes || []);
    } catch (err) {
      console.error('DashboardPage loadAll error:', err);
    }
  };

  useEffect(() => {
    loadAll();
    const intervalId = setInterval(loadAll, 2200);
    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });

    socket.on('fraud_alert', loadAll);
    socket.on('fraud_detected', loadAll);
    socket.on('risk_log', loadAll);
    socket.on('trade_inserted', loadAll);
    socket.on('trust_score_updated', loadAll);

    return () => {
      clearInterval(intervalId);
      socket.disconnect();
    };
  }, []);

  const loopOnly = useMemo(
    () =>
      cycles.filter(
        (c) => Array.isArray(c?.cycle) && c.cycle.length >= 4
      ),
    [cycles]
  );

  const nonLoopRiskLogs = useMemo(
    () =>
      riskLogs.filter(
        (log) => !String(log?.reason || '').includes('Circular trading loop detected')
      ),
    [riskLogs]
  );

  const computed = useMemo(() => {
    const totalTrades = Number(stats?.total_trades ?? trades.length ?? 0);
    const fraudRings = Number(stats?.fraud_rings_detected ?? loopOnly.length ?? 0);
    const highRisk = Number(stats?.high_risk_traders ?? 0);
    const monitored = Number(stats?.monitored_traders ?? stats?.total_traders ?? 0);
    const abnormalEntries = nonLoopRiskLogs.filter((log) =>
      String(log?.reason || '').toLowerCase().includes('abnormal price')
    ).length;

    return {
      totalTrades,
      fraudRings,
      highRisk,
      monitored,
      abnormalEntries,
    };
  }, [stats, trades, loopOnly, nonLoopRiskLogs]);

  return (
    <div className="page-wrap grid-bg">
      <div className="page-container">
        <div style={{ marginBottom: 24 }}>
          <h1 style={{ fontSize: 30, fontWeight: 900, margin: 0, color: '#e8f5ef' }}>
            TraceNet <span style={{ color: '#7cffb5' }}>Dashboard</span>
          </h1>
          <div style={{ color: '#7f978c', marginTop: 10, fontSize: 14 }}>
            Cleaner split between detected loops and suspicious transaction signals
          </div>
        </div>

        <div className="kpi-grid" style={{ marginBottom: 18 }}>
          <StatCard
            label="Total Trades"
            value={computed.totalTrades}
            sub="All recorded market transactions"
            accent="#8bffc1"
          />
          <StatCard
            label="Detected Rings"
            value={computed.fraudRings}
            sub="Circular loops shown separately below"
            accent="#67f0a8"
          />
          <StatCard
            label="Abnormal Price Logs"
            value={computed.abnormalEntries}
            sub="Standalone non-loop price anomalies"
            accent="#b6ff8a"
          />
          <StatCard
            label="Monitored Traders"
            value={computed.monitored}
            sub={`High risk traders: ${computed.highRisk}`}
            accent="#8debd0"
          />
        </div>

        <div className="grid-2" style={{ marginBottom: 18, alignItems: 'start' }}>
          <DarkGlassPanel
            title="Detected Circular Loops"
            subtitle="Loops stay here as explainable fraud rings, not mixed into the abnormal-price section"
            right={
              <span className="badge badge-low">
                {loopOnly.length} ring{loopOnly.length === 1 ? '' : 's'}
              </span>
            }
          >
            <div className="scroll-y" style={{ maxHeight: 340 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Stock</th>
                    <th>Loop Path</th>
                    <th>Trade Path</th>
                    <th>Depth</th>
                    <th>Confidence</th>
                  </tr>
                </thead>
                <tbody>
                  {loopOnly.slice(0, 12).map((item, idx) => (
                    <tr key={`${item.group_id || item.trade_id}-${idx}`}>
                      <td>{item.symbol || `#${item.stock_id}`}</td>
                      <td style={{ color: '#84ffb7', fontWeight: 800 }}>
                        {Array.isArray(item.cycle) ? item.cycle.join(' → ') : '—'}
                      </td>
                      <td style={{ color: '#90a79c' }}>
                        {Array.isArray(item.trade_path) ? item.trade_path.join(' → ') : '—'}
                      </td>
                      <td>{item.max_depth ?? item.depth ?? '—'}</td>
                      <td>
                        <span className={badgeClass(item.confidence || 0)}>
                          {item.confidence || 0}
                        </span>
                      </td>
                    </tr>
                  ))}
                  {!loopOnly.length && (
                    <tr>
                      <td colSpan="5">
                        <div className="empty-state">
                          No circular loops detected yet.
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </DarkGlassPanel>

          <div style={{ display: 'grid', gap: 18 }}>
            <div
              className="glass-strong"
              style={{
                padding: 20,
                background:
                  'linear-gradient(180deg, rgba(14,22,18,0.78), rgba(4,8,8,0.70))',
                border: '1px solid rgba(125,255,214,0.10)',
              }}
            >
              <div style={{ fontSize: 16, fontWeight: 900, marginBottom: 6 }}>
                Suspicious Trend Graph
              </div>
              <div style={{ color: '#7b9087', fontSize: 12, marginBottom: 12 }}>
                Only non-loop suspicious risk events are plotted here
              </div>
              <TrendChart logs={nonLoopRiskLogs} />
            </div>

            <DarkGlassPanel
              title="Quick Actions"
              subtitle="Keep only the useful navigation here"
            >
              <div style={{ display: 'flex', gap: 12, padding: 18, flexWrap: 'wrap' }}>
                <button className="btn-outline" onClick={() => navigate('/fraud')}>
                  Fraud Engine
                </button>
                <button className="btn-outline" onClick={() => navigate('/traders')}>
                  Traders
                </button>
              </div>
            </DarkGlassPanel>
          </div>
        </div>

        <DarkGlassPanel
          title="Suspicious Transaction Log"
          subtitle="Abnormal price, repeated patterns, and trust-based suspicious events"
          right={
            <span className="badge badge-medium">
              {nonLoopRiskLogs.length} entries
            </span>
          }
        >
          <div className="scroll-y" style={{ maxHeight: 340 }}>
            <table className="data-table">
              <thead>
                <tr>
                  <th>Trade ID</th>
                  <th>Risk</th>
                  <th>Label</th>
                  <th>Reason</th>
                  <th>Detected</th>
                </tr>
              </thead>
              <tbody>
                {nonLoopRiskLogs.slice(0, 20).map((log, idx) => (
                  <tr key={`${log.risk_id || log.trade_id}-${idx}`}>
                    <td>#{log.trade_id}</td>
                    <td>{log.risk_score}</td>
                    <td>
                      <span className={badgeClass(log.risk_score)}>
                        {log.risk_label || 'SUSPICIOUS'}
                      </span>
                    </td>
                    <td style={{ maxWidth: 650 }}>{log.reason}</td>
                    <td>{formatTime(log.detected_at)}</td>
                  </tr>
                ))}
                {!nonLoopRiskLogs.length && (
                  <tr>
                    <td colSpan="5">
                      <div className="empty-state">
                        No non-loop suspicious events yet.
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </DarkGlassPanel>
      </div>
    </div>
  );
}
